DO $m$ DECLARE s text; BEGIN SELECT pg_get_functiondef(oid) INTO s FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='kpi_source_value'; EXECUTE replace(s,'FUNCTION public.kpi_source_value(','FUNCTION public.kpi_source_value_legacy('); END $m$;
CREATE OR REPLACE FUNCTION public.kpi_source_value(_cp uuid,_month date,_key text,_avg boolean DEFAULT false) RETURNS numeric LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $f$ DECLARE val numeric; source_key text; BEGIN source_key:=CASE WHEN _key LIKE 'social.%' THEN substr(_key,8) WHEN _key LIKE 'gbp.%' THEN substr(_key,5) ELSE NULL END; IF source_key IS NOT NULL THEN SELECT (coalesce(f.corrected_values,f.fetched_values)->>source_key)::numeric INTO val FROM kpi_fetched_values f WHERE f.client_pipeline_id=_cp AND f.month=date_trunc('month',_month)::date AND f.status='approved' AND coalesce(f.corrected_values,f.fetched_values) ? source_key ORDER BY approved_at DESC LIMIT 1; IF FOUND THEN RETURN val; END IF; END IF; RETURN public.kpi_source_value_legacy(_cp,_month,_key,_avg); END $f$;
REVOKE ALL ON FUNCTION public.kpi_source_value_legacy(uuid,date,text,boolean) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.q57_refresh_reports_after_approval() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $f$ BEGIN IF NEW.status='approved' AND OLD.status<>'approved' THEN PERFORM public._refresh_report_kpis(r.id) FROM monthly_reports r WHERE r.client_pipeline_id=NEW.client_pipeline_id AND r.month=NEW.month AND r.status<>'approved'; END IF; RETURN NEW; END $f$;
CREATE TRIGGER q57_refresh_reports_after_approval AFTER UPDATE ON public.kpi_fetched_values FOR EACH ROW EXECUTE FUNCTION public.q57_refresh_reports_after_approval();